.ds {
  color:var(--p-ink); background:var(--p-bg); font:var(--p-type-body);
  color-scheme:light; word-break:keep-all; overflow-wrap:anywhere; text-align:left;
}
.ds,.ds * { box-sizing:border-box; }
.ds [hidden] { display:none!important; }
.ds :is(h1,h2,h3,p,fieldset) { margin:0; }
.ds :is(button,input,select,textarea) { font:inherit; color:inherit; letter-spacing:inherit; }
.ds :is(code,pre) { font-family:var(--p-mono-font); }
.ds button { cursor:pointer; touch-action:manipulation; }
.ds button:disabled { cursor:not-allowed; }
.ds :is(button,input,select,textarea,a,[tabindex]):focus-visible { outline:var(--p-border-width-focus) solid var(--p-highlight); outline-offset:var(--p-focus-offset); }
.ds .ui-icon { display:inline-block; width:var(--p-icon-lg); height:var(--p-icon-lg); object-fit:contain; flex-shrink:0; vertical-align:middle; }
.ds .ds-demo-note { font-size:var(--p-text-sm); margin-top:var(--p-space-sm); min-height:calc(var(--p-space-unit) * 5); color:var(--p-muted); }
.ds .ds-surface { border:var(--p-border-width) solid var(--p-line); border-radius:var(--p-radius); background:var(--p-surface); }
.ds .ds-surface[data-material="raised"] { box-shadow:var(--p-shadow); border-color:var(--p-edge); }
.ds .ds-surface[data-material="inset"] { box-shadow:var(--p-inset); background:var(--p-bg); }
.ds .ds-surface[data-material="glass"] { background:var(--p-high); box-shadow:var(--p-glass-shadow); }
@supports (backdrop-filter:blur(0)) { .ds .ds-surface[data-material="glass"] { background:var(--p-glass); backdrop-filter:var(--p-blur-md); } }
@media(prefers-reduced-transparency:reduce) { .ds .ds-surface[data-material="glass"] { background:var(--p-high); backdrop-filter:none; } }
@media(prefers-reduced-motion:reduce) { .ds * { transition:none!important; animation:none!important; } }
.ds .ds-token-row { display:flex; flex-wrap:wrap; align-items:center; gap:var(--p-space-sm); }
.ds .ds-admin-error { color:var(--p-error); font-size:var(--p-text-body); }

/* a number pinned to the icon corner, so nobody opens the box to count what piled up */
.ds .ds-count-badge { position:relative; display:inline-grid; place-items:center; width:var(--p-control-size-sm); height:var(--p-control-size-sm); flex-shrink:0; color:var(--p-ink); }
.ds .ds-count-badge .ui-icon { width:var(--p-icon-lg); height:var(--p-icon-lg); }
.ds .ds-badge-count { position:absolute; top:var(--p-space-3xs); right:0; display:inline-grid; place-items:center; min-width:calc(var(--p-space-unit) * 5); height:calc(var(--p-space-unit) * 5); padding:0 var(--p-space-2xs); border-radius:var(--p-radius-full); background:var(--p-accent); color:var(--p-on-accent); box-shadow:0 0 0 var(--p-border-width-strong) var(--p-bg); font-size:var(--p-text-sm); font-weight:var(--p-weight-bold); line-height:var(--p-leading-none); font-variant-numeric:tabular-nums; }

import React from 'react';
// How many new items wait on the icon (children). The number is read as "새 알림 N개", hides at zero and shows 99+ above 99.
export function CountBadge({ children, count = 0, ...props }) {
  return <span role="img" aria-label={count > 0 ? `새 알림 ${count}개` : '새 알림 없음'} {...props} className="ds-count-badge">{children}{count > 0 && <span className="ds-badge-count" aria-hidden="true">{count > 99 ? '99+' : count}</span>}</span>;
}

